// MUTATION doesn't trigger OnPush -- classic silent bug
@Component({ changeDetection: ChangeDetectionStrategy.OnPush })
export class ListComponent {
  items = signal<Item[]>([]);

  addItemWrong(item: Item) {
    this.items().push(item);        // ❌ mutates in place -- template never updates
  }

  addItemRight(item: Item) {
    this.items.update(list => [...list, item]);   // ✓ new reference -- triggers update
  }
}

// @for with a BAD track expression -- compiles fine, wrong at runtime
@for (item of items(); track $index) {   // ❌ index-based tracking breaks on reorder
  <item-card [item]="item" />
}
@for (item of items(); track item.id) {  // ✓ stable identity survives reordering
  <item-card [item]="item" />
}

// Reading @Input() too early
export class UserCard {
  user = input.required<User>();
  constructor() {
    console.log(this.user());   // ❌ throws or is undefined -- inputs not resolved yet
  }
  ngOnInit() {
    console.log(this.user());   // ✓ safe -- inputs are guaranteed set by now
  }
}

// switchMap on a SAVE action -- silently cancels the first save
saveBtn.click$.pipe(
  switchMap(() => this.api.save(this.form.value))   // ❌ 2nd click cancels 1st save
).subscribe();

saveBtn.click$.pipe(
  exhaustMap(() => this.api.save(this.form.value))  // ✓ ignores clicks while saving
).subscribe();

